// Station metadata mapping corresponding to Open-Meteo multi-coordinate responses
const STATIONS = [
  {
    id: 'LOC-MAITRI',
    name: 'Maitri Station',
    sector: 'Antarctica (Queen Maud Land)',
    latitude: -70.767,
    longitude: 11.733
  },
  {
    id: 'LOC-BHARATI',
    name: 'Bharati Station',
    sector: 'Antarctica (Larsemann Hills)',
    latitude: -69.407,
    longitude: 76.185
  },
  {
    id: 'LOC-HIMADRI',
    name: 'Himadri Station',
    sector: 'Arctic (Ny-Alesund, Svalbard)',
    latitude: 78.923,
    longitude: 11.928
  }
];

// Operational limits aligned with Polar Command Center logic
const OPS_LIMITS = {
  GROUNDED: { gusts: 74, windChill: -45 },
  HAZARDOUS: { gusts: 56, windChill: -35 },
  MARGINAL: { gusts: 39, windChill: -25 }
};

const items = $input.all();
const results = [];

// Open-Meteo returns an array of objects when querying multiple coordinates
const weatherData = Array.isArray(items[0]?.json) ? items[0].json : [items[0]?.json];

for (let i = 0; i < STATIONS.length; i++) {
  const station = STATIONS[i];
  const raw = weatherData[i] || {};
  const current = raw.current || {};

  const temp = Number(current.temperature_2m ?? 0);
  const gusts = Number(current.wind_gusts_10m ?? 0);
  const windChill = Number(current.apparent_temperature ?? temp);
  const weatherCode = current.weather_code ?? 0;
  const windSpeed = Number(current.wind_speed_10m ?? 0);

  let opsStatus = 'NORMAL';
  let severity = 'LOW';
  let reason = 'Conditions within safe operational limits';
  let hasHazard = false;

  if (gusts >= OPS_LIMITS.GROUNDED.gusts || windChill <= OPS_LIMITS.GROUNDED.windChill) {
    opsStatus = 'GROUNDED';
    severity = 'CRITICAL';
    hasHazard = true;
    reason = gusts >= OPS_LIMITS.GROUNDED.gusts
      ? `Extreme wind gusts (${gusts} km/h >= ${OPS_LIMITS.GROUNDED.gusts} km/h threshold)`
      : `Extreme wind chill (${windChill}°C <= ${OPS_LIMITS.GROUNDED.windChill}°C threshold)`;
  } else if (gusts >= OPS_LIMITS.HAZARDOUS.gusts || windChill <= OPS_LIMITS.HAZARDOUS.windChill) {
    opsStatus = 'HAZARDOUS';
    severity = 'HIGH';
    hasHazard = true;
    reason = gusts >= OPS_LIMITS.HAZARDOUS.gusts
      ? `Hazardous wind gusts (${gusts} km/h >= ${OPS_LIMITS.HAZARDOUS.gusts} km/h threshold)`
      : `Dangerous wind chill (${windChill}°C <= ${OPS_LIMITS.HAZARDOUS.windChill}°C threshold)`;
  } else if (gusts >= OPS_LIMITS.MARGINAL.gusts || windChill <= OPS_LIMITS.MARGINAL.windChill) {
    opsStatus = 'MARGINAL';
    severity = 'MEDIUM';
    hasHazard = false; // Logged for situational awareness
    reason = `Marginal operating window (${gusts} km/h gusts, wind chill ${windChill}°C)`;
  }

  results.push({
    json: {
      hasHazard,
      opsStatus,
      severity,
      station_id: station.id,
      station_name: station.name,
      sector: station.sector,
      latitude: station.latitude,
      longitude: station.longitude,
      telemetry: {
        temperature: temp,
        apparentTemperature: windChill,
        windGusts: gusts,
        windSpeed,
        weatherCode
      },
      reason,
      hazardDescription: hasHazard
        ? `[Automated n8n Weather Telemetry Alert] ${station.name}: ${reason}. Traverse and aerial operations suspended.`
        : null,
      evaluatedAt: new Date().toISOString()
    }
  });
}

return results;

// Deduplicate against existing active weather emergencies in Supabase
const hazardContext = $('Assess Ops Limits & Detect Hazards').item.json;
const existing = $input.first()?.json?.body || [];

const alreadyReported = Array.isArray(existing) && existing.length > 0;

if (alreadyReported) {
  return [{
    json: {
      skipCreation: true,
      reason: `Active incident already exists for ${hazardContext.station_id} (ID: ${existing[0].id})`,
      existingIncidentId: existing[0].id,
      hazardContext
    }
  }];
}

// Generate a unique incident key formatted to the PCC schema 'INC-XXXX'
const randomSuffix = Math.floor(1000 + Math.random() * 9000);
const incidentId = `INC-${randomSuffix}`;

const incidentPayload = {
  id: incidentId,
  type: 'WEATHER',
  location: `${hazardContext.station_name} Field Perimeter`,
  location_id: hazardContext.station_id,
  latitude: hazardContext.latitude,
  longitude: hazardContext.longitude,
  severity: hazardContext.severity,
  description: hazardContext.hazardDescription,
  status: 'ACTIVE',
  reported_at: new Date().toISOString(),
  assigned_team: `${hazardContext.station_name} Base Safety Unit`,
  response_note: `Automated alert triggered by n8n Open-Meteo monitor: ${hazardContext.reason}`
};

return [{
  json: {
    skipCreation: false,
    incidentId,
    incidentPayload,
    hazardContext
  }
}];

// Audit inventory items where current quantity <= minimum_quantity
const items = $input.all();
const lowStockAlerts = [];

for (const item of items) {
  const row = item.json;
  const qty = Number(row.quantity ?? 0);
  const minQty = Number(row.minimum_quantity ?? 0);

  if (qty <= minQty) {
    lowStockAlerts.push({
      id: row.id,
      item_name: row.item_name,
      category: row.category,
      current_quantity: qty,
      minimum_required: minQty,
      deficit: minQty - qty,
      unit: row.unit,
      location: row.location,
      condition: row.condition,
      status: 'LOW_STOCK'
    });
  }
}

return [{
  json: {
    auditedAt: new Date().toISOString(),
    totalLowStockCount: lowStockAlerts.length,
    items: lowStockAlerts,
    summaryMessage: `[Inventory Audit] ${lowStockAlerts.length} stock item(s) are critically low or depleted.`
  }
}];

// Normalizes incoming dispatch webhook payloads from frontend or satphones
const body = $input.first()?.json?.body || $input.first()?.json || {};

const id = body.id || `INC-${Math.floor(1000 + Math.random() * 9000)}`;
const type = (body.type || 'OTHER').toUpperCase();
const location = body.location || 'Unknown Polar Sector';
const location_id = body.location_id || 'LOC-MAITRI';
const severity = (body.severity || 'HIGH').toUpperCase();
const description = body.description || 'Manual emergency dispatch received via n8n webhook';

const incidentRecord = {
  id,
  type,
  location,
  location_id,
  latitude: Number(body.latitude ?? -70.767),
  longitude: Number(body.longitude ?? 11.733),
  severity,
  description,
  status: 'ACTIVE',
  reported_at: new Date().toISOString(),
  assigned_team: body.assigned_team || 'Base Emergency Response Unit',
  personnel_id: body.personnel_id || null,
  expedition_id: body.expedition_id || null
};

return [{
  json: {
    source: 'WEBHOOK_DISPATCH',
    incidentRecord
  }
}];

// Prepare formatted alert broadcast payload for downstream messaging (Slack, Discord, Email, Webhook)
const weatherIncidents = $('POST New Incident to Supabase').all() || [];
const webhookIncidents = $('Insert Webhook Incident to Supabase').all() || [];
const inventoryAudit = $('Audit Low-Stock Levels').first()?.json || {};

const createdIncidents = [
  ...weatherIncidents.map(i => i.json),
  ...webhookIncidents.map(i => i.json)
];

const title = '🚨 [POLAR COMMAND CENTER] Automation Dispatch Summary';
const timestamp = new Date().toISOString();

return [{
  json: {
    title,
    timestamp,
    incidentCount: createdIncidents.length,
    createdIncidents,
    lowStockSummary: inventoryAudit,
    status: 'DISPATCH_COMPLETE'
  }
}];
